246		}
247	
248		status, err := worktree.Status()
249		if err != nil {
250			return nil, fmt.Errorf("failed to get status: %w", err)
251		}
252	
253		// Build set of pre-existing untracked files for quick lookup
254		var preExisting map[string]bool
255		if previouslyUntracked != nil {
256			preExisting = make(map[string]bool, len(previouslyUntracked))
257			for _, f := range previouslyUntracked {
258				preExisting[f] = true
259			}
260		}
261	
262		var changes FileChanges
263		for file, st := range status {
264			if paths.IsInfrastructurePath(file) {
265				continue
266			}
267	
268			switch {
269			case st.Worktree == git.Untracked:
270				if preExisting != nil {
271					if !preExisting[file] {
272						changes.New = append(changes.New, file)
273					}
274				} else {
275					changes.New = append(changes.New, file)
276				}
277			case st.Worktree == git.Deleted || st.Staging == git.Deleted:
278				changes.Deleted = append(changes.Deleted, file)
279			case st.Worktree == git.Modified || st.Staging == git.Modified ||
280				st.Worktree == git.Added || st.Staging == git.Added:
281				changes.Modified = append(changes.Modified, file)
282			}
283		}
284	
285		return &changes, nil
