305	// Uses the git CLI instead of go-git to avoid index lock contention on Windows and
306	// to ensure consistent autocrlf/eol handling (git CLI respects system-level config,
307	// while go-git's content comparison would need manual CRLF normalization).
308	func filterToUncommittedFiles(ctx context.Context, files []string, repoRoot string) []string {
309		if len(files) == 0 {
310			return files
311		}
312	
313		// git diff --name-only HEAD -- <files> prints only files that differ from HEAD.
314		// Empty output means all files match HEAD (already committed). Exit 0 on success,
315		// non-zero (128) only on fatal errors (no HEAD, not a repo, etc.).
316		args := append([]string{"diff", "--name-only", "HEAD", "--"}, files...)
317		cmd := exec.CommandContext(ctx, "git", args...)
318		cmd.Dir = repoRoot
319		out, err := cmd.Output()
320		if err != nil {
321			// Fail open: no HEAD (empty repo, initial commit), not a git repo, etc.
322			logging.Warn(ctx, "filterToUncommittedFiles: git diff failed, keeping all files as uncommitted",
323				slog.String("error", err.Error()))
324			return files
325		}
326	
327		trimmed := strings.TrimRight(string(out), "\n")
328		if trimmed == "" {
329			return nil // all files are committed with matching content
330		}
331	
332		// Build a set of files that actually differ from HEAD.
333		diffSet := make(map[string]bool)
334		for _, line := range strings.Split(trimmed, "\n") {
335			if line != "" {
336				diffSet[filepath.ToSlash(line)] = true
337			}
338		}
