155	// ToRelativePath converts an absolute path to relative.
156	// Returns empty string if the path is outside the working directory.
157	func ToRelativePath(absPath, cwd string) string {
158		absPath = NormalizeMSYSPath(absPath)
159		if !filepath.IsAbs(absPath) {
160			return absPath
161		}
162		relPath, err := filepath.Rel(cwd, absPath)
163		if err != nil || strings.HasPrefix(relPath, "..") {
164			return ""
165		}
166	
167		return relPath
168	}
169	
170	// msysDrivePrefix matches MSYS/Git-Bash-style absolute paths like /c/ or /D/.
171	// Git for Windows executes hooks through MSYS2 bash, which converts Windows paths
172	// (C:\Users\...) to Unix-style (/c/Users/...) in tool output and transcripts.
173	var msysDrivePrefix = regexp.MustCompile(`^/([a-zA-Z])/`)
174	
175	// NormalizeMSYSPath converts MSYS/Git-Bash paths to Windows paths.
176	// Handles two MSYS conventions:
177	//   - Drive paths: /c/Users/... → C:/Users/...
178	//   - Virtual dirs: /tmp/... → <TEMP>/... (MSYS2 maps /tmp to the Windows temp dir)
179	//
180	// Returns the input unchanged on non-Windows or if the path doesn't match.
181	func NormalizeMSYSPath(p string) string {
182		if m := msysDrivePrefix.FindStringSubmatch(p); m != nil {
183			return strings.ToUpper(m[1]) + ":/" + p[3:]
